// Some portions generated by Claude
// Some portions generated by Codex
import { useDeferredValue, useId, useMemo, useState, type KeyboardEvent, type RefObject } from "react";
import { exactSearchResource, requiresManualRepositorySearch } from "./repository-search.ts";
import { findNodes } from "./graph-find.ts";
import { compactTerm } from "./graph-terms.ts";
import type { GraphNode } from "./graph-types.ts";
import { Icon } from "./icons.tsx";

export type FindFieldProps = {
  /** The nodes on the canvas. */
  nodes: readonly GraphNode[];
  busy: boolean;
  /** A recent statement count, or unknown. Unknown keeps repository searches manual. */
  repositorySize?: number | null;
  onFocusSearch?: () => void;
  inputRef: RefObject<HTMLInputElement | null>;
  /** Shows the node's details and brings it into view. */
  onReveal: (nodeId: string) => void;
  /** Adds the repository's resources that match the term to the graph. */
  onSearchRepository: (term: string) => void;
};

/** Loaded nodes are searched while typing. Repository-wide label scans are a separate deliberate action. */
export function FindField({ nodes, busy, inputRef, onReveal, onSearchRepository, repositorySize, onFocusSearch }: FindFieldProps) {
  const listId = useId();
  const [term, setTerm] = useState("");
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const deferredTerm = useDeferredValue(term);
  const options = useMemo(() => findNodes(nodes, deferredTerm), [nodes, deferredTerm]);
  const shown = open && Boolean(term.trim());
  const current = Math.min(active, options.length - 1);
  const upToDate = term === deferredTerm;
  const exactResource = exactSearchResource(term.trim());
  const manual = requiresManualRepositorySearch(repositorySize);
  const searchRepository = () => {
    if (busy || !term.trim()) return;
    onSearchRepository(term.trim());
    setOpen(false);
  };
  const chooseNode = (index: number) => {
    if (!upToDate || !options[index]) return;
    onReveal(options[index].node.id);
    setOpen(false);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      if (!options.length) return;
      setOpen(true);
      const step = event.key === "ArrowDown" ? 1 : -1;
      setActive(shown ? (current + step + options.length) % options.length : 0);
    } else if (event.key === "Enter") {
      event.preventDefault();
      if (!upToDate) return;
      if (options.length) chooseNode(shown ? current : 0);
      else if (exactResource || !manual) searchRepository();
      else setOpen(true);
    } else if (event.key === "Escape") {
      if (shown) {
        event.stopPropagation();
        setOpen(false);
      } else if (term) {
        event.stopPropagation();
        setTerm("");
      }
    }
  };

  return (
    <div className="graph-find" role="search" onBlur={(event) => {
      if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setOpen(false);
    }}>
      <Icon name="search" />
      <input
        ref={inputRef}
        type="search"
        role="combobox"
        aria-label="Find a node, or search the repository"
        aria-keyshortcuts="/"
        title="Find a node (/)"
        aria-autocomplete="list"
        aria-expanded={shown}
        aria-controls={shown && options.length > 0 && upToDate ? listId : undefined}
        aria-activedescendant={shown && options.length > 0 && upToDate ? `${listId}-${current}` : undefined}
        placeholder="Find in the loaded graph…"
        value={term}
        onChange={(event) => {
          setTerm(event.target.value);
          setActive(0);
          setOpen(true);
        }}
        onFocus={() => { setOpen(true); onFocusSearch?.(); }}
        onKeyDown={onKeyDown}
      />
      {shown ? (
        <div className="graph-find-results">
          {options.length > 0 && upToDate ? (
            <ul id={listId} role="listbox" aria-label="Loaded graph matches">
              {options.map((match, index) => (
                <li key={match.node.id} id={`${listId}-${index}`} role="option"
                  aria-selected={index === current} className={index === current ? "is-active" : ""}
                  onMouseDown={(event) => event.preventDefault()}
                  onMouseEnter={() => setActive(index)} onClick={() => chooseNode(index)}>
                  <span className="graph-find-label">{match.node.label}</span>
                  <small>{match.in === "iri" ? compactTerm(match.node.id, 48) : (match.node.types?.[0]?.label ?? "")}</small>
                </li>
              ))}
            </ul>
          ) : <p className="graph-find-empty">{upToDate ? "No matches in the loaded graph" : "Finding loaded nodes…"}</p>}
          <button type="button" className="graph-find-repository" disabled={busy}
            onClick={searchRepository} title={busy ? "Available when the current query is done" : term.trim()}>
            <Icon name="search" />{exactResource ? "Load this resource" : "Search entire repository"}
          </button>
          {!exactResource && manual ? <p className="graph-find-hint">
            {repositorySize == null ? "Repository size is unknown." : "More than 100,000 statements."} Search may take time.
          </p> : null}
        </div>
      ) : null}
    </div>
  );
}
